package pl.mkrstudio.truefootball3.audio
import java.io.File
import pl.mkrstudio.truefootball3.lab.TtsHealthStatus
object TtsSettingsStore{const val DEFAULT_VI_SYLLABLES_PER_SEC=4.2f;fun estimateVietnameseSpeechDurationMs(text:String,rate:Float)=1000L}
class MatchTtsManager{data class Selection(val targetSyllablesPerSec:Float=4.2f);data class Request(val file:File,val ready:(Long)->Unit);val requests=linkedMapOf<String,Request>();val played=mutableListOf<Triple<String,Float,Long>>();var completion:(()->Unit)?=null;var offset=0L;var rate=1f;fun currentSelection()=Selection();fun isEnabled()=true;fun setHealthListener(f:(TtsHealthStatus,String)->Unit){};fun currentWavPositionMs()=offset;fun updateActivePlaybackRate(r:Float){rate=r};fun reportHealthy(s:String){};fun reportBacklogDegraded(s:String){};fun pauseWavPlayback(){};fun resumeWavPlayback(){};fun stopWavPlayback(){completion=null};fun synthesizeCueToWav(cueId:String,text:String,outFile:File,onReady:(Long)->Unit,onError:(String)->Unit){requests[cueId]=Request(outFile,onReady)};fun ready(id:String,ms:Long=1000){val r=requests.getValue(id);r.file.writeText("fake wav");r.ready(ms)};fun playWavAtRate(wavFile:File,playbackRate:Float,startOffsetMs:Long,onComplete:()->Unit,onError:(String)->Unit){check(completion==null);played.add(Triple(wavFile.nameWithoutExtension,playbackRate,startOffsetMs));completion=onComplete};fun complete(){val f=checkNotNull(completion);completion=null;f()}}
